light.css:
background: #fffbf1;
color: #694323;
box-shadow:
  inset 0 0 0 1px rgb(129 91 31 / 0.24),
  inset 0 2px 3px rgb(129 91 31 / 0.14),
  0 1px 0 rgb(255 255 255 / 0.9);
/* ::placeholder */ color: #936b4a;
/* :focus-visible */
box-shadow:
  inset 0 0 0 1.5px #8e6ac7,
  0 0 0 3px rgb(142 106 199 / 0.35);

/* checkbox / radio, off */
background: #fffbf1;
box-shadow:
  inset 0 0 0 1.5px #af95df,
  inset 0 1px 2px rgb(111 79 161 / 0.20),
  0 0 0 3px rgb(217 199 252 / 0.45);
/* on: same shadow, plus */
background: #d9c7fc;   /* tick or dot drawn in #522e0b */

/* switch track off / slider track */
background: #f7ecd1;
box-shadow: inset 0 0 0 1.5px #af95df, inset 0 1px 3px rgb(129 91 31 / 0.25);
/* switch track on */    background: #d9c7fc;
/* slider filled range */ background: #af95df;
/* thumb */
background: #fffbf1;
box-shadow: 0 0 0 1px rgb(111 79 161 / 0.18), 0 1px 3px rgb(111 79 161 / 0.40);

dark.css:
background: var(--fill);   /* same four hexes as light mode */
color: #522e0b;
box-shadow:
  inset 0 1px 0 rgb(255 255 255 / 0.45),
  0 0 0 1px rgb(var(--fill-rgb) / 0.30),
  0 6px 20px -6px rgb(var(--fill-rgb) / 0.35);
/* --fill-rgb: lilac 217 199 252 | blush 251 191 195 | butter 239 222 161 | robin 190 233 238 */

background: #160f09;
color: #f0e7d2;
box-shadow:
  inset 0 0 0 1px rgb(254 245 224 / 0.20),
  inset 0 2px 4px rgb(0 0 0 / 0.45),
  0 1px 0 rgb(254 245 224 / 0.10);
/* ::placeholder */ color: #c8bca5;
/* :focus-visible */
box-shadow:
  inset 0 0 0 1.5px #c6b1f0,
  0 0 0 3px rgb(217 199 252 / 0.30);

/* off */
background: #160f09;
box-shadow:
  inset 0 0 0 1.5px rgb(217 199 252 / 0.60),
  0 0 0 3px rgb(217 199 252 / 0.14);
/* on: same shadow, plus */
background: #d9c7fc;   /* tick or dot in #472400; slider filled range also #d9c7fc */
/* thumb */
background: #fef5e0;
box-shadow: 0 1px 3px rgb(0 0 0 / 0.5);
